import{_ as o,o as a,c as t,a0 as l}from"./chunks/framework.QP0FkqbW.js";const u=JSON.parse('{"title":"Установка и настройка KUKA KRL Professional","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guide/installation.md","filePath":"ru/guide/installation.md"}'),r={name:"ru/guide/installation.md"};function i(n,e,s,d,c,g){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="установка-и-настроика-kuka-krl-professional" tabindex="-1">Установка и настройка KUKA KRL Professional <a class="header-anchor" href="#установка-и-настроика-kuka-krl-professional" aria-label="Permalink to &quot;Установка и настройка KUKA KRL Professional&quot;">​</a></h1><p>Руководство по быстрой установке и началу работы с расширением.</p><h2 id="_1-установка-из-vs-code-marketplace" tabindex="-1">1. Установка из VS Code Marketplace <a class="header-anchor" href="#_1-установка-из-vs-code-marketplace" aria-label="Permalink to &quot;1. Установка из VS Code Marketplace&quot;">​</a></h2><ol><li>Откройте VS Code.</li><li>Перейдите во вкладку расширений (<code>Ctrl + Shift + X</code>).</li><li>Введите в поиске <code>KUKA KRL Professional</code>.</li><li>Нажмите <strong>Install</strong>.</li></ol><h2 id="_2-установка-из-vsix-фаила-offline-installation" tabindex="-1">2. Установка из VSIX-файла (Offline Installation) <a class="header-anchor" href="#_2-установка-из-vsix-фаила-offline-installation" aria-label="Permalink to &quot;2. Установка из VSIX-файла (Offline Installation)&quot;">​</a></h2><ol><li>Скачайте файл <code>kuka-krl-extension-1.7.3.vsix</code>.</li><li>В VS Code выберите меню <code>...</code> в правом верхнем углу панели Extensions.</li><li>Нажмите <strong>Install from VSIX...</strong> и выберите файл.</li></ol><h2 id="_3-выбор-темы-оформления-kuka" tabindex="-1">3. Выбор темы оформления KUKA <a class="header-anchor" href="#_3-выбор-темы-оформления-kuka" aria-label="Permalink to &quot;3. Выбор темы оформления KUKA&quot;">​</a></h2><ol><li>Нажмите <code>Ctrl + K</code>, затем <code>Ctrl + T</code>.</li><li>Выберите одну из 6 фирменных тем: <strong>Industrial Dark</strong>, <strong>WorkVisual Dark</strong>, <strong>WorkVisual Light</strong>, <strong>Midnight OLED</strong>, <strong>Blueprint</strong>, <strong>Industrial Light</strong>.</li></ol><h2 id="_4-активация-pro-лицензии" tabindex="-1">4. Активация Pro Лицензии <a class="header-anchor" href="#_4-активация-pro-лицензии" aria-label="Permalink to &quot;4. Активация Pro Лицензии&quot;">​</a></h2><ol><li>Откройте <strong>KUKA Control Center</strong> нажатием на иконку KUKA в Activity Bar или по команде <code>KRL: Open Control Center</code>.</li><li>Нажмите кнопку <strong>Enter License Key</strong>.</li><li>Вставьте ваш лицензионный ключ от Lemon Squeezy и нажмите <strong>Activate</strong>.</li></ol><h2 id="_5-поддержка-в-telegram" tabindex="-1">5. Поддержка в Telegram <a class="header-anchor" href="#_5-поддержка-в-telegram" aria-label="Permalink to &quot;5. Поддержка в Telegram&quot;">​</a></h2><p>По всем вопросам вы можете связаться с инженером поддержки через встроенный чат в VS Code или напрямую с ботом <strong><code>@kukakrlbot</code></strong> в Telegram.</p>',12)])])}const k=o(r,[["render",i]]);export{u as __pageData,k as default};
